SELECT 'user_two_factor_audit_events.fk_2fa_audit_user' AS fk, COUNT(*) AS orphan_count FROM user_two_factor_audit_events c LEFT JOIN users p ON c.user_id=p.id WHERE c.user_id IS NOT NULL AND p.id IS NULL;
SELECT 'user_two_factor_challenges.fk_challenge_user' AS fk, COUNT(*) AS orphan_count FROM user_two_factor_challenges c LEFT JOIN users p ON c.user_id=p.id WHERE c.user_id IS NOT NULL AND p.id IS NULL;
SELECT 'user_two_factor_methods.fk_factor_user' AS fk, COUNT(*) AS orphan_count FROM user_two_factor_methods c LEFT JOIN users p ON c.user_id=p.id WHERE c.user_id IS NOT NULL AND p.id IS NULL;
